    'cool': ['heating8', 'sleep', 'floor'],
    'dry': ['high_power', 'eco', 'silent1', 'silent2', 'heating8', 'sleep', 'floor'],
    'fan': ['high_power', 'eco', 'silent1', 'silent2', 'heating8', 'sleep', 'floor'],
    'heat': []
};

// Translation of options labels (french is the reference language)
msg.payload.translate = {
    'en': {
        'Froid': 'Cooling',
        'Chaud': 'Heating',
        'Déshumidificateur': 'Dehumidifier',
        'Ventilation': 'Fan',
        'Silence': 'Silent',
        'Vitesse 1': 'Speed 1',
        'Vitesse 2': 'Speed 2',
        'Vitesse 3': 'Speed 3',
        'Vitesse 4': 'Speed 4',
        'Vitesse 5': 'Speed 5',
        'Fixe': 'Fixed',
        'Vertical': 'Vertical',
        'Horizontal': 'Horizontal',
        'Toutes directions': 'All directions',
        'Position 1': 'Position 1',
        'Position 2': 'Position 2',
        'Position 3': 'Position 3',
        'Position 4': 'Position 4',
        'Position 5': 'Position 5',
        'Aucune': 'None',
        'Puissance maximale': 'High power',
        'Unité extérieure silencieuse 1': 'Silent outdoor unit 1',
        'Unité extérieure silencieuse 2': 'Silent outdoor unit 2',
        'Hors gel 8 °C': 'Frost protection 8 °C',
        'Sommeil': 'Sleep',
        'Chauffage au sol': 'Floor heating',
        'Confort': 'Comfort'
    }
};

const e = msg.payload.enum;

// control entry: [name, entity, group, type, unit, default value, options: {key: name}, ha type, ha state_class, ha device_class, device field]
msg.payload.control = {
    'unit': {
        'fault': ['Défaut', 'fault', 'sensor', 'binary', '', true, {}, 'binary_sensor', '', 'problem', 'fault'],
        'state': ['Etat', 'state', 'command', 'binary', '', false, {}, 'switch', '', '', 'power'],
        'mode': ['Mode', 'mode', 'command', 'enum', '', 'auto', e.mode, 'select', '', '', 'mode'],
        'temperatureSetpoint': ['Consigne', 'temperatureSetpoint', 'command', 'number', '°C', 20, {}, 'number', '', 'temperature', 'setpoint'],
        'fanRate': ['Ventilation', 'fanRate', 'command', 'enum', '', 'auto', e.fanRate, 'select', '', '', 'fanRate'],
        'fanDirection': ['Direction', 'fanDirection', 'command', 'enum', '', 'off', e.fanDirection, 'select', '', '', 'fanDirection'],
        'powerLimit': ['Puissance', 'powerLimit', 'command', 'enum', '', '100', e.powerLimit, 'select', '', '', 'powerLimit'],
        'preset': ['Fonction', 'preset', 'command', 'enum', '', 'off', e.preset, 'select', '', '', 'preset'],
        'purifier': ['Purificateur', 'purifier', 'command', 'binary', '', false, {}, 'switch', '', '', 'purifier'],
        'temperatureIndoor': ['Intérieur', 'temperatureIndoor', 'sensor', 'number', '°C', 0, {}, 'sensor', 'measurement', 'temperature', 'indoor'],
        'temperatureOutdoor': ['Extérieur', 'temperatureOutdoor', 'sensor', 'number', '°C', 0, {}, 'sensor', 'measurement', 'temperature', 'outdoor'],
        'energy': ['Energie', 'energy', 'sensor', 'number', 'Wh', 0, {}, 'sensor', 'total_increasing', 'energy', 'energy']
    }
};

// Icons of the options in the dashboard
msg.payload.icon = {
    'power': { '0': 'power-off', '1': 'power-cycle' },
    'mode': { 'auto': 'refresh-auto', 'cool': 'snowflake', 'heat': 'fire', 'dry': 'water-percent', 'fan': 'weather-windy' },
    'fanRate': { 'auto': 'refresh-auto', 'quiet': 'leaf', '1': 'fan-minus', '2': 'fan-speed-1', '3': 'fan-speed-2', '4': 'fan-speed-3', '5': 'fan-plus' },
    'fanDirection': { 'off': 'arrow-collapse-all', 'vertical': 'arrow-up-down', 'horizontal': 'arrow-left-right', 'both': 'arrow-all' },
    'purifier': { '0': 'air-filter', '1': 'air-purifier' }
};

return msg;

// Build a Toshiba API request
// msg.api: { operation: login | register | mapping | state | energy, acId (state), ids (energy) }
// output 1: http request / output 2: invalid request, back to caller

const conf = global.get('describe.api', 'memoryOnly') || {};
const account = global.get('account', 'default') || {};
const api = msg.api;

function refuse(error, transient) {
    msg.result = { 'ok': false, 'status': 0, 'data': null, 'error': error, 'auth': false, 'rate': false, 'badlogin': false, 'transient': transient };

    return [null, msg];
}

if (typeof api !== 'object' || api === null || typeof (conf.path || {})[api.operation] !== 'string' || typeof account.user !== 'string' || account.user === '') {

    return refuse('Requête invalide', false);
}

// Toshiba blocks too frequent requests
const pause = flow.get('api_pause', 'memoryOnly') || 0;
if (Date.now() < pause) {

    return refuse('Accès suspendu jusqu\'à ' + new Date(pause).toLocaleTimeString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris' }), true);
}

const op = api.operation;
const logged = typeof account.token === 'string' && account.token !== '';

if (op !== 'login' && !logged) {
    msg.result = { 'ok': false, 'status': 401, 'data': null, 'error': 'Session expirée', 'auth': true, 'rate': false, 'badlogin': false, 'transient': false };

    return [null, msg];
}

let query = {};
let body = null;

if (op === 'login') {
    body = { 'Username': account.user, 'Password': String(account.password || '') };
} else if (op === 'register') {
    body = { 'DeviceID': account.user + '_' + account.device, 'DeviceType': '1', 'Username': account.user };
} else if (op === 'mapping') {
    query = { 'consumerId': account.consumerId };
} else if (op === 'state') {
    query = { 'ACId': api.acId, 'consumerId': account.consumerId };
} else if (op === 'energy') {
    const year = new Date().getUTCFullYear();
    body = {
        'ACDeviceUniqueIdList': Array.isArray(api.ids) ? api.ids : [],
        'FromUtcTime': String(year),
        'Timezone': 'UTC',
        'ToUtcTime': String(year + 1),
        'Type': 'EnergyYear'
    };
}

// Toshiba firewall: the application sends its device identifier with every request (HTTP 429 without it)
// and a browser User-Agent is refused (HTTP 403), so an empty one is sent
msg.headers = {
    'Content-Type': 'application/json',
    'Device-ID': account.device,
    'User-Agent': ''
};
if (op !== 'login') {
    msg.headers.Authorization = (account.tokenType || 'Bearer') + ' ' + account.token;
}

const params = Object.keys(query).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(String(query[k] === undefined || query[k] === null ? '' : query[k]))).join('&');

msg.method = body === null ? 'GET' : 'POST';
msg.url = (env.get('DKNR_TOSHIBA_URL') || conf.url) + conf.path[op] + (params !== '' ? '?' + params : '');
msg.requestTimeout = 20000;
msg.payload = body === null ? '' : body;

node.status({ fill: 'blue', shape: 'ring', text: op });

return [msg, null];

// Send the request to Toshiba
// The HTTP request node always adds a User-Agent, which Toshiba firewall refuses: the request is sent without it
// output 1: answer (msg.statusCode, msg.payload, msg.headers)

const target = new URL(msg.url);
const lib = global.get(target.protocol === 'http:' ? 'http' : 'https');
const body = msg.method === 'POST' ? JSON.stringify(msg.payload) : '';

let headers = {};
for (const k in msg.headers) {
    if (msg.headers[k] !== '') {
        headers[k] = msg.headers[k];
    }
}
if (body !== '') {
    headers['Content-Length'] = Buffer.byteLength(body);
}

let ended = false;
function end(status, payload, answer) {
    if (ended) {

        return;
    }
    ended = true;
    msg.statusCode = status;
    msg.payload = payload;
    msg.headers = answer || {};
    node.send(msg);
    node.done();
}

const req = lib.request(target, { 'method': msg.method, 'headers': headers, 'timeout': msg.requestTimeout || 20000 }, res => {
    let chunks = [];
    res.on('data', c => chunks.push(c));
    res.on('end', () => end(res.statusCode, Buffer.concat(chunks).toString(), res.headers));
    res.on('error', e => end(undefined, String(e.message || e)));
});
req.on('timeout', () => req.destroy(new Error('timeout')));
req.on('error', e => end(undefined, String(e.message || e)));
req.end(body);

return;

// Normalize a Toshiba API response then go back to caller
// msg.result: { ok, status, data, error, auth, rate, badlogin, transient }

const api = msg.api || {};

let raw = msg.payload;
if (Buffer.isBuffer(raw)) {
    raw = raw.toString();
}

let body = raw;
if (typeof raw === 'string') {
    try {
        body = JSON.parse(raw);
    } catch (e) {
        body = null;
    }
}

let result = {
    'ok': false,
    'status': msg.statusCode,
    'data': null,
    'error': '',
    'auth': false,
    'rate': false,
    'badlogin': false,
    'transient': false
};

if (typeof msg.statusCode !== 'number') {
    result.error = 'Toshiba injoignable';
    result.transient = true;
} else if (msg.statusCode === 401) {
    result.error = 'Session expirée';
    result.auth = true;
} else if (msg.statusCode === 403 || msg.statusCode === 429) {
    // Toshiba blocks too frequent requests: no request for the asked time (429), 15 minutes otherwise
    const said = typeof body === 'object' && body !== null ? String(body.message || body.Message || '') : '';
    const asked = Number((/(\d+)\s*second/i.exec(said) || [])[1]) || Number((msg.headers || {})['retry-after']) || 0;
    const wait = msg.statusCode === 429 ? Math.min(Math.max(asked, 60), 900) : 900;
    result.error = 'Accès temporairement bloqué par Toshiba (trop de requêtes), nouvel essai possible dans ' + (wait >= 120 ? Math.round(wait / 60) + ' minutes' : wait + ' secondes') + (said !== '' ? ' - ' + said : '');
    result.rate = true;
    result.transient = true;
    flow.set('api_pause', Date.now() + wait * 1000, 'memoryOnly');
} else if (msg.statusCode !== 200) {
    result.error = 'HTTP ' + msg.statusCode;
    result.transient = msg.statusCode >= 500;
} else if (typeof body !== 'object' || body === null) {
    result.error = 'Réponse invalide';
    result.transient = true;
} else if (body.IsSuccess === true) {
    result.ok = true;
    result.data = body.ResObj;
} else {
    result.error = String(body.Message || body.StatusCode || 'Erreur');
    // a refused password is not always given with the same code
    result.badlogin = body.StatusCode === 'InvalidUserNameorPassword' || api.operation === 'login' && /password|lock/i.test(result.error);
}

msg.result = result;

// Last answer, shown in account page
flow.set('api_last', {
    'operation': api.operation,
    'status': result.status,
    'error': result.error,
    'at': Date.now()
}, 'memoryOnly');

// Do not keep secrets in message
delete msg.headers;
delete msg.url;
delete msg.method;
delete msg.requestTimeout;
delete msg.responseUrl;
delete msg.redirectList;
delete msg.retry;
delete msg.error;
delete msg.statusCode;
msg.payload = '';

if (result.ok) {
    node.status({ fill: 'green', shape: 'dot', text: api.operation });
} else {
    node.status({ fill: 'red', shape: 'ring', text: api.operation + ' : ' + result.error });
}

return msg;

// Toshiba session: login, registration to the cloud messages, list of the units, periodic reads
// input: topic boot | tick | login | logout | refresh | reload (payload = id), or an API answer (msg.api + msg.result)
// output 1: API request / output 2: cloud connection / output 3: notification / output 4: unit state / output 5: discovery / output 6: refresh UI

const crypto = global.get('crypto');
const describe = global.get('describe', 'memoryOnly') || {};
const conf = describe.api || {};
const now = Date.now();

let account = global.get('account', 'default') || {};

const known = typeof account.user === 'string' && account.user !== '';
const keyed = known && typeof account.password === 'string' && account.password !== '';

function save() {
    global.set('account', account, 'default');
}

function api(operation, extra, chain) {

    return [{ 'api': { 'operation': operation, ...(extra || {}) }, 'chain': chain || msg.chain || '' }, null, null, null, null, null];
}

function start(operation, extra, chain) {
    flow.set('busy', now, 'memoryOnly');
    flow.set('last_' + operation, now, 'memoryOnly');

    return api(operation, extra, chain);
}

function done(text) {
    flow.set('busy', 0, 'memoryOnly');

    return [null, null, text ? { 'payload': text } : null, null, null, { 'payload': '' }];
}

// Units able to report their consumption
function meters() {
    const units = global.get('units', 'default') || {};

    return Object.keys(units).filter(id => units[id].energy === true);
}

// What a unit can do, from its "merit feature" bits and its model
function features(merit, model) {
    const bits = parseInt((String(merit || '') + '0000').slice(0, 4), 16) || 0;
    const bit = n => ((bits >> (15 - n)) & 1) === 1;

    let options = {
        'mode': ['auto', 'cool', 'heat', 'dry', 'fan'],
        'fanRate': ['auto', 'quiet', '1', '2', '3', '4', '5'],
        'fanDirection': ['off', 'vertical'],
        'powerLimit': ['50', '75', '100'],
        'preset': ['off', 'sleep', 'comfort']
    };
    let purifier = false;
    let energy = false;

    if (!bit(6) && bit(7)) {
        options.mode = ['heat'];
    } else if (bit(6) && !bit(7)) {
        options.mode = ['auto', 'cool', 'dry', 'fan'];
    }

    if (['2', '3'].includes(String(model))) {
        options.preset.push('high_power', 'eco');
        if (bit(0)) {
            options.preset.push('floor');
        }
        if (bit(1)) {
            options.fanDirection.push('horizontal', 'both');
        }
        if (bit(2)) {
            options.preset.push('silent1', 'silent2');
        }
        if (bit(3)) {
            purifier = true;
        }
        if (bit(5)) {
            options.preset.push('heating8');
        }
    }

    if (String(model) === '3') {
        if (bit(14)) {
            options.fanDirection.push('fixed1', 'fixed2', 'fixed3', 'fixed4', 'fixed5');
        }
        if (bit(15)) {
            energy = true;
        }
    }

    return { 'options': options, 'purifier': purifier, 'energy': energy };
}

// Connection to the cloud messages (Azure IoT Hub over MQTT) with the token given by Toshiba
function connect() {
    let host = conf.hub;
    let device = account.user + '_' + account.device;

    // token resource: host/devices/id
    try {
        const sr = decodeURIComponent((/[?&\s]sr=([^&]+)/.exec(account.sas) || [])[1] || '').split('/');
        if (sr.length >= 3 && sr[1] === 'devices') {
            host = sr[0];
            device = sr.slice(2).join('/');
        }
    } catch (e) { }

    let broker = {
        'broker': host,
        'port': 8883,
        'usetls': true,
        'verifyservercert': true
    };

    // other server, for tests: host:port without TLS
    const other = String(env.get('DKNR_TOSHIBA_HUB') || '').split(':');
    if (other[0] !== '') {
        broker = { 'broker': other[0], 'port': Number(other[1]) || 1883, 'usetls': false, 'verifyservercert': false };
    }

    flow.set('cloud_device', device, 'memoryOnly');

    return [
        {
            'action': 'connect',
            'broker': {
                ...broker,
                'clientid': device,
                'username': host + '/' + device + '/?api-version=' + conf.version,
                'password': account.sas,
                'protocolVersion': 4,
                'keepalive': 60,
                'cleansession': true,
                'force': true
            }
        },
        // messages from the units come as direct methods
        { 'action': 'subscribe', 'topic': [{ 'topic': '$iothub/methods/POST/#', 'qos': 1 }], 'payload': '' }
    ];
}

const disconnect = { 'action': 'disconnect' };

// ---- API answers

if (typeof msg.api === 'object' && msg.api !== null && typeof msg.result === 'object') {
    const op = msg.api.operation;
    const r = msg.result;
    const data = r.data;

    // session closed by Toshiba: one new login then the same request again
    if (r.auth === true && op !== 'login') {
        account.token = '';
        save();
        if (msg.api.again === true || !keyed) {

            return done(msg.chain === 'login' ? 'Connexion à Toshiba impossible : session refusée' : '');
        }
        const next = { ...msg.api, 'again': true };
        flow.set('last_login', now, 'memoryOnly');

        return [{ 'api': { 'operation': 'login' }, 'chain': msg.chain || '', 'next': next }, null, null, null, null, null];
    }

    if (op === 'login') {
        if (r.ok === true && typeof data === 'object' && data !== null && typeof data.access_token === 'string' && data.access_token !== '') {
            account.token = data.access_token;
            account.tokenType = String(data.token_type || 'Bearer');
            account.consumerId = String(data.consumerId || '');
            account.status = 'ok';
            save();

            if (typeof msg.next === 'object' && msg.next !== null) {

                return [{ 'api': msg.next, 'chain': msg.chain || '' }, null, null, null, null, null];
            }

            return start('register');
        }

        account.token = '';
        if (r.badlogin === true) {
            // never try again with a refused password, Toshiba could block the account
            account.password = '';
            account.status = 'reauth';
            save();

            flow.set('busy', 0, 'memoryOnly');

            return [null, disconnect, { 'payload': 'Connexion refusée par Toshiba : identifiant ou mot de passe incorrect' }, null, null, { 'payload': '' }];
        }
        // a first connection which fails is forgotten, a known account will try again later
        if (account.status === 'login') {
            account.status = '';
            account.password = '';
        }
        save();

        return done(['login', 'refresh'].includes(msg.chain) ? 'Connexion à Toshiba impossible : ' + (r.error || 'réponse inattendue') : '');
    }

    if (op === 'register') {
        if (r.ok === true && typeof data === 'object' && data !== null && typeof data.SasToken === 'string' && data.SasToken !== '') {
            account.sas = data.SasToken;
            // expiration of the token (ms), one hour if unknown
            const se = Number((/[?&]se=(\d+)/.exec(data.SasToken) || [])[1]);
            account.sasExp = se > 0 ? se * 1000 : now + 3600000;
            save();

            node.send([null, connect(), null, null, null, null]);

            return start('mapping');
        }

        return done(msg.chain === 'login' ? 'Enregistrement auprès de Toshiba impossible : ' + (r.error || 'réponse inattendue') : '');
    }

    if (op === 'mapping') {
        if (r.ok !== true || !Array.isArray(data)) {

            return done(['login', 'refresh'].includes(msg.chain) ? 'Lecture des climatiseurs impossible : ' + (r.error || 'réponse inattendue') : '');
        }

        const old = global.get('units', 'default') || {};
        let devices = global.get('devices', 'memoryOnly') || {};
        let units = {};
        let states = [];

        for (const group of data) {
            for (const ac of ((group || {}).ACList || [])) {
                if (typeof ac !== 'object' || ac === null || !ac.DeviceUniqueId) {

                    continue;
                }
                const id = String(ac.DeviceUniqueId);
                const f = features(ac.MeritFeature, ac.ACModelId);

                units[id] = {
                    'id': id,
                    'acId': String(ac.Id || ''),
                    'name': String(ac.Name || 'Climatiseur'),
                    'model': String(ac.ACModelId || ''),
                    'merit': String(ac.MeritFeature || ''),
                    'firmware': String(ac.FirmwareVersion || ''),
                    'indoor': (old[id] || {}).indoor || '',
                    'outdoor': (old[id] || {}).outdoor || '',
                    'options': f.options,
                    'purifier': f.purifier,
                    'energy': f.energy
                };

                devices[id] = { ...(devices[id] || {}), 'id': id, 'family': 'unit', 'name': units[id].name };
                states.push({ 'topic': id, 'payload': { 'data': String(ac.ACStateData || '') } });
            }
        }

        // units removed from the account
        for (const id in devices) {
            if (typeof units[id] !== 'object') {
                delete devices[id];
            }
        }

        const changed = JSON.stringify(Object.keys(units).sort().map(id => [id, units[id].name, units[id].options, units[id].purifier, units[id].energy]))
            !== JSON.stringify(Object.keys(old).sort().map(id => [id, old[id].name, old[id].options, old[id].purifier, old[id].energy]));

        global.set('units', units, 'default');
        global.set('devices', devices, 'memoryOnly');
        flow.set('last_mapping', now, 'memoryOnly');

        node.send([null, null, null, states, null, null]);

        if (changed) {
            node.send([null, null, null, null, { 'topic': 'discovery', 'payload': '' }, null]);
        }

        const text = msg.chain === 'login' ? 'Connecté à Toshiba : ' + Object.keys(units).length + ' climatiseur(s)' : '';
        const ids = meters();

        if (ids.length > 0 && (msg.chain !== '' || now - (flow.get('last_energy', 'memoryOnly') || 0) > 900000)) {
            node.send([null, null, text ? { 'payload': text } : null, null, null, { 'payload': '' }]);

            return start('energy', { 'ids': ids }, '');
        }

        return done(text);
    }

    if (op === 'state') {
        if (r.ok !== true || typeof data !== 'object' || data === null) {

            return;
        }

        // models of the indoor and outdoor units
        let units = global.get('units', 'default') || {};
        const id = msg.api.id;
        if (typeof units[id] === 'object') {
            const indoor = String((data.Fcu || {}).model_name || units[id].indoor || '');
            const outdoor = String((data.Cdu || {}).model_name || units[id].outdoor || '');
            if (indoor !== units[id].indoor || outdoor !== units[id].outdoor) {
                units[id].indoor = indoor;
                units[id].outdoor = outdoor;
                global.set('units', units, 'default');
            }
        }

        return [null, null, null, typeof data.ACStateData === 'string' ? { 'topic': id, 'payload': { 'data': data.ACStateData } } : null, null, null];
    }

    if (op === 'energy') {
        flow.set('busy', 0, 'memoryOnly');
        if (r.ok !== true || !Array.isArray(data)) {

            return;
        }

        let states = [];
        for (const ac of data) {
            if (typeof ac !== 'object' || ac === null || !Array.isArray(ac.EnergyConsumption)) {

                continue;
            }
            let total = 0;
            let valid = false;
            for (const item of ac.EnergyConsumption) {
                const v = Number((item || {}).Energy);
                if (!isNaN(v)) {
                    total += v;
                    valid = true;
                }
            }
            if (valid) {
                states.push({ 'topic': String(ac.ACDeviceUniqueId), 'payload': { 'energy': Math.round(total) } });
            }
        }

        return [null, null, null, states, null, null];
    }

    return;
}

// ---- Requests

const busy = now - (flow.get('busy', 'memoryOnly') || 0) < 90000;
const last = k => now - (flow.get('last_' + k, 'memoryOnly') || 0);

if (msg.topic === 'login') {
    const p = msg.payload || {};
    const user = String(p.user || '').trim();
    const password = String(p.password || '');

    if (account.status === 'ok') {

        return [null, null, { 'payload': 'Un compte est déjà connecté, déconnectez-le avant' }, null, null, null];
    }
    if (user === '' || password === '') {

        return [null, null, { 'payload': 'Identifiant et mot de passe requis' }, null, null, null];
    }
    if (busy) {

        return [null, null, { 'payload': 'Connexion déjà en cours, patientez' }, null, null, null];
    }

    // The identifier of this installation for Toshiba is kept for a known user
    const same = account.user === user && typeof account.device === 'string' && account.device !== '';

    account = {
        'user': user,
        'password': password,
        'device': same ? account.device : crypto.randomBytes(8).toString('hex'),
        'token': '',
        'tokenType': '',
        'consumerId': '',
        'sas': '',
        'sasExp': 0,
        'status': 'login'
    };
    save();

    return start('login', {}, 'login');
}

if (msg.topic === 'logout') {
    flow.set('busy', 0, 'memoryOnly');
    flow.set('cloud_device', '', 'memoryOnly');

    return [null, disconnect, null, null, null, null];
}

// nothing more without an account already connected once
if (!keyed || account.status !== 'ok') {
    // a connection never ended (restart during a login)
    if (account.status === 'login' && !busy) {
        account.status = '';
        account.password = '';
        save();

        return [null, null, null, null, null, { 'payload': '' }];
    }

    return;
}

if (msg.topic === 'boot') {
    // a connection just done from the dashboard
    if (last('login') < 60000) {

        return;
    }
    account.token = '';
    save();

    return start('login', {}, 'boot');
}

if (busy) {

    return;
}

if (msg.topic === 'reload') {
    const units = global.get('units', 'default') || {};
    const id = String(msg.payload || '');
    if (typeof units[id] !== 'object') {

        return;
    }

    return api('state', { 'id': id, 'acId': units[id].acId }, '');
}

if (msg.topic === 'refresh') {
    if (last('mapping') < 20000) {

        return;
    }

    return start('mapping', {}, 'refresh');
}

if (msg.topic !== 'tick') {

    return;
}

const cloud = flow.get('cloud', 'memoryOnly') || {};

// no session: a new login, 10 minutes after the last one at least
if (account.token === '') {

    return last('login') > 600000 ? start('login', {}, '') : null;
}

// cloud token about to expire, or cloud lost for 2 minutes: a new token and a new connection
if (!account.sas || account.sasExp - now < 900000) {

    return last('register') > 300000 ? start('register', {}, '') : null;
}
if (cloud.connected !== true && now - (cloud.since || 0) > 120000 && last('register') > 600000) {

    return start('register', {}, '');
}

// states of the units every 15 minutes, their changes are received from the cloud in between
if (last('mapping') > 900000) {

    return start('mapping', {}, '');
}

const ids = meters();
if (ids.length > 0 && last('energy') > 900000) {

    return start('energy', { 'ids': ids }, '');
}

return;

// Message from Toshiba cloud: the units send their state as direct methods of Azure IoT Hub
// topic: $iothub/methods/POST/<method>/?$rid=<request id>
// output 1: answer to the cloud / output 2: unit state

const m = /^\$iothub\/methods\/POST\/([^/]+)\/\?\$rid=(.+)$/.exec(String(msg.topic || ''));
if (m === null) {

    return;
}

// every method is acknowledged
const ack = { 'topic': '$iothub/methods/res/0/?$rid=' + m[2], 'payload': 'null', 'qos': 0, 'retain': false };

let data = msg.payload;
if (Buffer.isBuffer(data)) {
    data = data.toString();
}
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        data = null;
    }
}

if (m[1] !== 'smmobile' || typeof data !== 'object' || data === null || typeof data.sourceId !== 'string' || typeof data.payload !== 'object' || data.payload === null) {

    return [ack, null];
}

node.status({ text: data.cmd + ' ' + new Date().toLocaleTimeString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris' }) });

if (data.cmd === 'CMD_FCU_FROM_AC' && typeof data.payload.data === 'string') {

    return [ack, { 'topic': data.sourceId, 'payload': { 'data': data.payload.data } }];
}

if (data.cmd === 'CMD_HEARTBEAT') {

    return [ack, { 'topic': data.sourceId, 'payload': { 'heartbeat': data.payload } }];
}

return [ack, null];

// Connection state of Toshiba cloud messages, from the status of the MQTT node
// output 1: refresh UI

const connected = (msg.status || {}).fill === 'green';
const old = flow.get('cloud', 'memoryOnly') || {};

if (old.connected === connected) {

    return;
}

flow.set('cloud', { 'connected': connected, 'since': Date.now() }, 'memoryOnly');

node.status(connected ? { fill: 'green', shape: 'dot', text: 'connecté' } : { fill: 'red', shape: 'ring', text: 'déconnecté' });

return { 'payload': '' };

// State of a unit, from Toshiba cloud
// input: topic = unit id, payload: { data: state frame (hex) } | { heartbeat: { iTemp, oTemp } } | { energy: Wh of the year }
// output 1: unit changed (topic = unit id)

const describe = global.get('describe', 'memoryOnly') || {};
const code = describe.code || {};
const units = global.get('units', 'default') || {};
const id = String(msg.topic || '');
const p = msg.payload || {};
const now = Date.now();

if (typeof units[id] !== 'object') {

    return;
}

let devices = global.get('devices', 'memoryOnly') || {};
let dev = { ...(devices[id] || {}), 'id': id, 'family': 'unit', 'name': units[id].name };
const before = JSON.stringify(dev);

// temperature of a signed byte, undefined when unknown
function temperature(raw) {
    const v = raw > 127 ? raw - 256 : raw;
    if (isNaN(v) || v === 127 || v === -128 || v === -1) {

        return undefined;
    }

    return v === 126 ? -1 : v;
}

function set(field, value) {
    if (value !== undefined) {
        dev[field] = value;
    }
}

if (typeof p.data === 'string' && /^[0-9a-fA-F]{38,}$/.test(p.data)) {
    // frame: state, mode, setpoint, fan rate, fan direction, power limit, functions (2 half bytes), purifier, indoor, outdoor, 4 unused, self cleaning, 4 unused
    // a value not sent is FF (or F for a half byte)
    const b = Buffer.from(p.data.slice(0, 38), 'hex');

    set('power', (code.power || {})[b[0]]);
    set('mode', (code.mode || {})[b[1]]);
    set('fanRate', (code.fanRate || {})[b[3]]);
    set('fanDirection', (code.fanDirection || {})[b[4]]);
    set('powerLimit', (code.powerLimit || {})[b[5]]);
    set('preset', (code.preset || {})[b[6] & 0x0F]);
    if (units[id].purifier === true) {
        set('purifier', (code.purifier || {})[b[7]]);
    }
    set('raw', temperature(b[2]));
    set('indoor', temperature(b[8]));
    set('outdoor', temperature(b[9]));
    if (b[14] !== 0xFF) {
        dev.cleaning = b[14] === 0x18;
    }

    // in frost protection the unit gives its setpoint with 16 degrees more
    if (typeof dev.raw === 'number') {
        dev.setpoint = dev.mode === 'heat' && dev.preset === 'heating8' ? dev.raw - 16 : dev.raw;
    }

    dev.updated = now;
} else if (typeof p.heartbeat === 'object' && p.heartbeat !== null) {
    set('indoor', temperature(parseInt(p.heartbeat.iTemp, 16)));
    set('outdoor', temperature(parseInt(p.heartbeat.oTemp, 16)));

    dev.updated = now;
} else if (typeof p.energy === 'number' && units[id].energy === true) {
    // consumption since the beginning of the year: its growth feeds the hours and days of the charts
    let history = global.get('history', 'default') || {};
    let h = history[id] || { 'last': null, 'hour': {}, 'day': {} };

    if (typeof h.last === 'number') {
        const delta = p.energy >= h.last ? p.energy - h.last : p.energy;
        if (delta > 0) {
            const d = new Date(now);
            const pad = n => String(n).padStart(2, '0');
            const day = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
            const hour = day + ' ' + pad(d.getHours());
            h.hour[hour] = (h.hour[hour] || 0) + delta;
            h.day[day] = (h.day[day] || 0) + delta;
        }
    }
    h.last = p.energy;

    // 2 days of hours and 35 days are kept
    const keep = (o, n) => { for (const k of Object.keys(o).sort().slice(0, -n)) { delete o[k]; } };
    keep(h.hour, 48);
    keep(h.day, 35);

    history[id] = h;
    global.set('history', history, 'default');

    dev.energy = p.energy;
} else {

    return;
}

devices[id] = dev;
global.set('devices', devices, 'memoryOnly');

const { updated: u1, ...a } = JSON.parse(before);
const { updated: u2, ...c } = dev;

if (JSON.stringify(a) === JSON.stringify(c)) {

    return;
}

node.status({ fill: 'green', shape: 'dot', text: dev.name + ' ' + new Date(now).toLocaleTimeString('fr-FR', { 'timeZone': env.get('TZ') || 'Europe/Paris' }) });

return { 'topic': id, 'payload': id };

// Fault of each unit: 1 when the account or the cloud is not connected, or without news of the unit for a while
// output 1: publish (topic = unit id) / output 2: discovery (new device) / output 3: refresh UI (fault changed)

const account = global.get('account', 'default') || {};
const units = global.get('units', 'default') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const cloud = flow.get('cloud', 'memoryOnly') || {};
const now = Date.now();

// units are read every 15 minutes: no valid read since 40 minutes
const timeout = 2400000;

// after a start, wait for the first reads
let start = context.get('start');
if (typeof start !== 'number') {
    start = now;
    context.set('start', start);
}

// cloud messages lost for 5 minutes
const lost = cloud.connected !== true && now - (cloud.since || start) > 300000;

let discovery = false;
let faults = 0;
let changed = false;

for (const id in units) {
    // unit not read yet (start without connection): only its fault is known
    if (typeof devices[id] !== 'object') {
        devices[id] = {
            'id': id,
            'family': 'unit',
            'name': units[id].name
        };
        discovery = true;
    }

    const last = devices[id].updated || start;
    const fault = account.status !== 'ok' || lost || now - last > timeout;

    if (fault) {
        faults++;
    }

    if (devices[id].fault !== fault) {
        changed = true;
    }

    devices[id].fault = fault;
    node.send([{ 'topic': id, 'payload': id }, null, null]);
}

global.set('devices', devices, 'memoryOnly');

node.status(faults > 0 ? { fill: 'red', shape: 'ring', text: faults + ' climatiseur(s) en défaut' } : { fill: 'green', shape: 'dot', text: 'ok' });

return [null, discovery ? { 'topic': 'discovery', 'payload': '' } : null, changed ? { 'payload': '' } : null];

// DKNR command: topic / set / toshiba / id / entity = value
// refresh entity: read the units now
// output 1: read units / output 2: unit command

const units = global.get('units', 'default') || {};
const describe = global.get('describe', 'memoryOnly') || {};
const control = (describe.control || {}).unit || {};

const path = String(msg.topic || '').split('/');
if (path.length < 5) {

    return;
}

const entity = path.pop();
const id = path.pop();
let value = (msg.payload === undefined || msg.payload === null ? '' : msg.payload).toString().trim();

node.status({ text: id + ' - ' + entity + ' - ' + value });

if (typeof units[id] !== 'object') {

    return;
}

// A retained command would be played again at each start
if (msg.retain === true) {
    node.status({ fill: 'red', shape: 'ring', text: id + ' - ' + entity + ' : commande retenue ignorée' });

    return;
}

if (entity === 'refresh') {

    return [{ 'topic': 'refresh', 'payload': '' }, null];
}

let def = undefined;
for (const k in control) {
    if (control[k][1] === entity && control[k][2] === 'command') {
        def = control[k];
    }
}

if (def === undefined) {

    return;
}

if (def[3] === 'enum') {
    // by key (DKNR) or by name in any language (Home Assistant select)
    const words = describe.translate || {};
    let key = undefined;
    for (const k in def[6]) {
        const names = [def[6][k]].concat(Object.keys(words).map(l => words[l][def[6][k]])).map(n => String(n).toLowerCase());
        if (k === value.toLowerCase() || names.includes(value.toLowerCase())) {
            key = k;
        }
    }
    if (key === undefined) {
        node.status({ fill: 'red', shape: 'ring', text: id + ' - ' + entity + ' - ' + value + ' : inconnu' });

        return;
    }
    value = key;
}
else if (def[3] === 'binary') {
    // 1 / 0 (ON / OFF accepted)
    const v = value.toUpperCase();
    if (['1', 'ON', 'TRUE'].includes(v)) {
        value = '1';
    } else if (['0', 'OFF', 'FALSE'].includes(v)) {
        value = '0';
    } else {
        node.status({ fill: 'red', shape: 'ring', text: id + ' - ' + entity + ' - ' + value + ' : inconnu' });

        return;
    }
}

return [null, { 'topic': id, 'payload': { 'id': id, 'entity': entity, 'value': value, 'source': 'mqtt' } }];

// Command of a unit, sent to Toshiba cloud
// input: topic = unit id, payload: { id, entity, value, source: ui | mqtt }
// output 1: cloud message / output 2: notification / output 3: check the state of the unit

const describe = global.get('describe', 'memoryOnly') || {};
const account = global.get('account', 'default') || {};
const units = global.get('units', 'default') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const cloud = flow.get('cloud', 'memoryOnly') || {};
const device = flow.get('cloud_device', 'memoryOnly') || '';
const p = msg.payload || {};
const id = String(p.id || '');
const unit = units[id];
const dev = devices[id] || {};
const control = (describe.control || {}).unit || {};

function refuse(text) {
    node.status({ fill: 'red', shape: 'ring', text: text });

    // commands from MQTT are refused silently
    return [null, p.source === 'ui' ? { 'payload': text } : null, null];
}

// code of a key
function code(field, key) {
    const codes = (describe.code || {})[field] || {};
    for (const c in codes) {
        if (String(codes[c]) === String(key)) {

            return Number(c);
        }
    }

    return undefined;
}

let def = undefined;
for (const k in control) {
    if (control[k][1] === p.entity && control[k][2] === 'command') {
        def = control[k];
    }
}

if (typeof unit !== 'object' || def === undefined) {

    return refuse('Commande inconnue');
}

if (account.status !== 'ok' || cloud.connected !== true || device === '') {

    return refuse('Toshiba non connecté, commande impossible');
}

const name = unit.name + ' - ' + def[0];
const value = String(p.value === undefined || p.value === null ? '' : p.value).trim();

// frame: state, mode, setpoint, fan rate, fan direction, power limit, functions (2 half bytes), purifier, indoor, outdoor, 4 unused, self cleaning, 4 unused
// only the changed value is sent, the others are FF
let frame = Buffer.alloc(19, 0xFF);

if (def[1] === 'state') {
    if (!['0', '1'].includes(value)) {

        return refuse(name + ' : valeur refusée');
    }
    frame[0] = code('power', value);
    // a unit in self cleaning does not start
    if (value === '1' && dev.cleaning === true) {
        frame[14] = 0x10;
    }
}
else if (def[1] === 'temperatureSetpoint') {
    // frost protection: 5 to 13 degrees, sent with 16 degrees more
    const frost = dev.mode === 'heat' && dev.preset === 'heating8';
    const min = frost ? 5 : 17;
    const max = frost ? 13 : 30;
    const t = Math.round(Number(value));
    if (value === '' || isNaN(t) || t < min || t > max) {

        return refuse(name + ' : de ' + min + ' à ' + max + ' °C');
    }
    frame[2] = frost ? t + 16 : t;
}
else if (def[1] === 'purifier') {
    if (unit.purifier !== true || !['0', '1'].includes(value)) {

        return refuse(name + ' : non disponible');
    }
    frame[7] = code('purifier', value);
}
else {
    // enum
    const field = def[10];
    const c = code(field, value);
    if (c === undefined || !((unit.options || {})[field] || []).includes(value)) {

        return refuse(name + ' : « ' + value + ' » non disponible sur ce climatiseur');
    }
    if (field === 'preset' && ((describe.refused || {})[dev.mode] || []).includes(value)) {

        return refuse(name + ' : « ' + def[6][value] + ' » non disponible dans ce mode');
    }

    if (field === 'mode') {
        frame[1] = c;
    } else if (field === 'fanRate') {
        frame[3] = c;
    } else if (field === 'fanDirection') {
        frame[4] = c;
    } else if (field === 'powerLimit') {
        frame[5] = c;
    } else if (field === 'preset') {
        frame[6] = 0xF0 | c;
    }
}

node.status({ fill: 'green', shape: 'dot', text: name + ' : ' + value });

return [
    {
        // device to cloud message with its properties: content type, encoding and type=mob
        'topic': 'devices/' + device + '/messages/events/%24.ct=application%2Fjson&%24.ce=utf-8&type=mob',
        'payload': JSON.stringify({
            'sourceId': device,
            'messageId': '0000000',
            'targetId': [id],
            'cmd': 'CMD_FCU_TO_AC',
            'payload': { 'data': frame.toString('hex') },
            'timeStamp': '0000000'
        }),
        'qos': 1,
        'retain': false
    },
    null,
    { 'topic': id, 'payload': id }
];

// Publish changed values of a unit to DKNR MQTT topic: topic / get / toshiba / id / entity

const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
const describe = global.get('describe', 'memoryOnly') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const source = 'toshiba';
const id = msg.topic;
const dev = devices[id];

if (!enabled || topic === '' || typeof dev !== 'object') {

    return;
}

function value(dev, def) {
    const raw = dev[def[10]];
    if (raw === undefined || raw === null || raw === '') {

        return undefined;
    }
    if (def[3] === 'enum') {

        // DKNR value is the key, labels are in discovery options
        return typeof def[6][String(raw)] === 'string' ? String(raw) : undefined;
    }
    if (def[3] === 'binary') {

        return raw === true || raw === 1 ? 1 : 0;
    }

    return raw;
}

const control = (describe.control || {})[dev.family] || {};

for (const k in control) {
    const v = value(dev, control[k]);
    if (v === undefined) {

        continue;
    }

    const last = 'last["' + id + '_' + control[k][1] + '"]';
    if (flow.get(last, 'memoryOnly') === v) {

        continue;
    }
    flow.set(last, v, 'memoryOnly');

    node.send({
        'topic': [topic, 'get', source, id, control[k][1]].join('/'),
        'payload': v,
        'qos': 0,
        'retain': true
    });
}

return;

// Publish DKNR discovery and Home Assistant MQTT discovery of all known units

const enabled = global.get('mqtt.enabled', 'default') || false;
const topic = global.get('mqtt.topic', 'default') || '';
const discovery = global.get('mqtt.homeassistant', 'default') || '';
const devices = global.get('devices', 'memoryOnly') || {};
const units = global.get('units', 'default') || {};
const describe = global.get('describe', 'memoryOnly') || {};
const source = 'toshiba';

// Options labels in the language of the MQTT configuration
const lang = global.get('mqtt.lang', 'default') || 'fr';
const words = (describe.translate || {})[lang] || {};
const tr = s => typeof s === 'string' && typeof words[s] === 'string' ? words[s] : s;
// Home Assistant template mapping a value with a dictionary
const haMap = m => '{{ ' + JSON.stringify(m) + '[value] | default(value) }}';

if (!enabled || topic === '') {

    return;
}

// Values are published again after a discovery
flow.set('last', {}, 'memoryOnly');

// Source definition
node.send({
    'topic': [topic, 'discovery', source].join('/'),
    'payload': describe.app,
    'qos': 0,
    'retain': true
});

for (const id in units) {
    const unit = units[id];
    const dev = devices[id] || {};
    const control = (describe.control || {}).unit || {};

    const device = {
        'identifiers': [
            ['dknr', source, id].join('_')
        ],
        'manufacturer': 'Toshiba',
        'model': unit.indoor || 'Toshiba',
        'name': 'Toshiba ' + unit.name
    };
    if (unit.firmware !== '') {
        device.sw_version = unit.firmware;
    }

    // Device definition
    node.send({
        'topic': [topic, 'discovery', source, id].join('/'),
        'payload': {
            'name': unit.name,
        },
        'qos': 0,
        'retain': true
    });

    for (const k in control) {
        const def = control[k];
        const key = def[1];

        // only entities available on this unit
        if (key === 'purifier' && unit.purifier !== true || key === 'energy' && unit.energy !== true) {

            continue;
        }

        // enum options available on this unit: key => translated label
        let options = {};
        if (def[3] === 'enum') {
            for (const o of ((unit.options || {})[def[10]] || [])) {
                if (typeof def[6][o] === 'string') {
                    options[o] = tr(def[6][o]);
                }
            }
        }

        // dknr
        node.send({
            'topic': [topic, 'discovery', source, id, key].join('/'),
            'payload': {
                'name': def[0],
                'group': def[2],
                'type': def[3],
                'unit': def[4],
                'value': def[3] === 'binary' ? (def[5] ? 1 : 0) : def[5],
                'options': options
            },
            'qos': 0,
            'retain': true
        });

        // ha
        if (discovery === '') {

            continue;
        }

        let payload = {
            'unique_id': ['dknr', source, id, key].join('_'),
            'name': def[0],
            'state_topic': [topic, 'get', source, id, key].join('/'),
            'device': device
        };

        if (def[7] === 'sensor') {
            payload.unit_of_measurement = def[4];
            payload.state_class = def[8];
            payload.device_class = def[9];
        }
        else if (def[7] === 'binary_sensor') {
            payload.payload_on = '1';
            payload.payload_off = '0';
            payload.device_class = def[9];
        }
        else if (def[7] === 'switch') {
            payload.command_topic = [topic, 'set', source, id, key].join('/');
            payload.payload_on = '1';
            payload.payload_off = '0';
            payload.state_on = '1';
            payload.state_off = '0';
        }
        else if (def[7] === 'select') {
            payload.command_topic = [topic, 'set', source, id, key].join('/');
            // by label, DKNR value is the key
            let reverse = {};
            for (const o in options) {
                reverse[options[o]] = o;
            }
            payload.options = Object.values(options);
            payload.value_template = haMap(options);
            payload.command_template = haMap(reverse);
        }
        else if (def[7] === 'number') {
            payload.command_topic = [topic, 'set', source, id, key].join('/');
            payload.unit_of_measurement = def[4];
            payload.device_class = def[9];
            // 5 to 13 in frost protection, 17 to 30 otherwise
            payload.min = 5;
            payload.max = 30;
            payload.step = 1;
        }
        else {

            continue;
        }

        node.send({
            'topic': [discovery, def[7], source, id + '_' + key, 'config'].join('/'),
            'payload': payload,
            'qos': 0,
            'retain': true
        });
    }
}

return;

// Publish the values of all units

const devices = global.get('devices', 'memoryOnly') || {};

return [Object.keys(devices).map(id => ({ 'topic': id, 'payload': id }))];

// Prepare the units for the dashboard

// a tab change to another page: nothing to do
if (typeof msg.tab === 'string' && msg.tab !== 'detail') {

    return null;
}

const describe = global.get('describe', 'memoryOnly') || {};
const account = global.get('account', 'default') || {};
const units = global.get('units', 'default') || {};
const devices = global.get('devices', 'memoryOnly') || {};
const cloud = flow.get('cloud', 'memoryOnly') || {};
const e = describe.enum || {};
const icon = describe.icon || {};

// options of an entity available on a unit
function options(unit, field) {

    return ((unit.options || {})[field] || []).filter(k => typeof (e[field] || {})[k] === 'string').map(k => ({
        'value': k,
        'label': e[field][k],
        'icon': (icon[field] || {})[k] ? 'mdi-' + icon[field][k] : ''
    }));
}

let list = [];
for (const id in units) {
    const unit = units[id];
    const dev = devices[id] || {};
    const frost = dev.mode === 'heat' && dev.preset === 'heating8';

    list.push({
        'id': id,
        'name': unit.name,
        'model': [unit.indoor, unit.outdoor].filter(m => m).join(' / '),
        'fault': dev.fault === true,
        'power': dev.power === 1 ? '1' : (dev.power === 0 ? '0' : ''),
        'mode': dev.mode || '',
        'setpoint': typeof dev.setpoint === 'number' ? dev.setpoint : null,
        'min': frost ? 5 : 17,
        'max': frost ? 13 : 30,
        'fanRate': dev.fanRate || '',
        'fanDirection': dev.fanDirection || '',
        'powerLimit': dev.powerLimit || '',
        'preset': dev.preset || '',
        'purifier': unit.purifier === true ? (dev.purifier === 1 ? '1' : '0') : null,
        'indoor': typeof dev.indoor === 'number' ? dev.indoor : null,
        'outdoor': typeof dev.outdoor === 'number' ? dev.outdoor : null,
        'energy': typeof dev.energy === 'number' ? dev.energy : null,
        'options': {
            'mode': options(unit, 'mode'),
            'fanRate': options(unit, 'fanRate'),
            'fanDirection': options(unit, 'fanDirection'),
            'powerLimit': options(unit, 'powerLimit'),
            // functions refused in the current mode are not proposed
            'preset': options(unit, 'preset').filter(o => !((describe.refused || {})[dev.mode] || []).includes(o.value))
        }
    });
}

let info = '';
if (typeof account.user !== 'string' || account.user === '') {
    info = 'Aucun compte, connectez-vous à Toshiba depuis la page Compte.';
} else if (account.status === 'reauth') {
    info = 'Connexion refusée par Toshiba, reconnectez-vous depuis la page Compte.';
} else if (account.status !== 'ok') {
    info = 'Compte non connecté, connectez-vous depuis la page Compte.';
} else if (list.length === 0) {
    info = 'Aucun climatiseur sur ce compte Toshiba.';
} else if (cloud.connected !== true) {
    info = 'Connexion à Toshiba en cours, les commandes ne sont pas encore possibles.';
}

return { 'payload': { 'units': list, 'info': info } };

// Action from the dashboard
// output 1: unit command / output 2: read units

const p = msg.payload || {};

if (msg.topic === 'refresh') {

    return [null, { 'topic': 'refresh', 'payload': '' }];
}

if (msg.topic !== 'set' || typeof p.id !== 'string' || typeof p.entity !== 'string') {

    return;
}

return [{ 'topic': p.id, 'payload': { 'id': p.id, 'entity': p.entity, 'value': p.value, 'source': 'ui' } }, null];

// Energy charts of the air conditioners, from the growth of the consumption given by Toshiba every 15 minutes
const FIELDS = [
    { 'key': 'energy', 'name': 'Consommation', 'slot': 1 }
];
const DAYS = ['dim.', 'lun.', 'mar.', 'mer.', 'jeu.', 'ven.', 'sam.'];
const DAYS_LONG = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const MONTHS_LONG = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];

function pad(n) {
    return String(n).padStart(2, '0');
}

// a tab change to another page: nothing to do
if (typeof msg.tab === 'string' && msg.tab !== 'chart') {
    return null;
}

const units = global.get('units', 'default') || {};
const history = global.get('history', 'default') || {};

if (msg.topic === 'select') {
    flow.set('current_chart', String(msg.payload || ''), 'memoryOnly');
}

// units able to report their consumption, the selected one is kept for all browsers
const meters = Object.keys(units).filter(id => units[id].energy === true).map(id => ({
    'value': id,
    'label': units[id].name || id
}));
let id = flow.get('current_chart', 'memoryOnly') || '';
if (!meters.some(m => m.value === id)) {
    id = meters.length > 0 ? meters[0].value : '';
    flow.set('current_chart', id, 'memoryOnly');
}

if (id === '') {
    return { 'payload': { 'error': Object.keys(units).length > 0 ? 'Aucun climatiseur de ce compte ne donne sa consommation.' : 'Aucun climatiseur, connectez-vous à Toshiba depuis la page Compte.', 'meters': [], 'periods': [], 'fields': [] } };
}

const h = history[id] || {};
const fields = FIELDS;

if (typeof h.last !== 'number') {
    return { 'payload': { 'error': 'Pas encore de consommation reçue de ce climatiseur, elle est relevée toutes les 15 minutes.', 'meters': meters, 'selected': id, 'periods': [], 'fields': [] } };
}

const now = new Date();

function bar(key, label, title, value) {
    return { 'key': key, 'label': label, 'title': title, 'values': value === undefined ? {} : { 'energy': value }, 'total': value || 0 };
}

// last 24 hours
let hours = [];
for (let i = 23; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 3600000);
    const hour = d.getHours();
    const key = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + ' ' + pad(hour);
    hours.push(bar('h' + i, hour + 'h', pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + ' de ' + hour + 'h à ' + ((hour + 1) % 24) + 'h', (h.hour || {})[key]));
}

// last 14 days
let days = [];
for (let i = 13; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
    const key = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
    days.push(bar('d' + i, DAYS[d.getDay()] + ' ' + d.getDate(), DAYS_LONG[d.getDay()] + ' ' + d.getDate() + ' ' + MONTHS_LONG[d.getMonth()], (h.day || {})[key]));
}

const periods = [
    { 'key': 'hour', 'title': 'Par heure, 24 dernières heures', 'bars': hours },
    { 'key': 'day', 'title': 'Par jour, 14 derniers jours', 'bars': days }
].map(p => Object.assign(p, { 'total': p.bars.reduce((a, b) => a + b.total, 0) }));

node.status({ fill: 'green', shape: 'dot', text: units[id].name + ' ' + now.toLocaleTimeString('fr-FR') });

return {
    'payload': {
        'error': '',
        'meters': meters,
        'selected': id,
        'fields': fields,
        'periods': periods,
        'updated': now.toLocaleString('fr-FR')
    }
};

// Prepare account page
// output 1: login form / output 2: table / output 3: logout button / output 4: groups to show / output 5: second pass

// a tab change to another page: nothing to do
if (typeof msg.tab === 'string' && msg.tab !== 'add') {

    return null;
}

const account = global.get('account', 'default') || {};
const units = global.get('units', 'default') || {};
const cloud = flow.get('cloud', 'memoryOnly') || {};
const status = account.status || '';
const known = typeof account.user === 'string' && account.user !== '';
const zone = { 'timeZone': env.get('TZ') || 'Europe/Paris' };

const hide = { 'payload': '', 'class': 'remove', 'enabled': false };
const show = { 'payload': '', 'class': '', 'enabled': true };

// login form, not shown when connected
let form = { 'topic': '', 'class': '', 'enabled': true, 'payload': { 'user': known ? account.user : '', 'password': '' } };
if (status === 'ok') {
    form = { 'topic': '', 'class': 'remove', 'enabled': false, 'payload': { 'user': '', 'password': '' } };
}

// account summary
const labels = {
    'ok': 'Connecté',
    'login': 'Connexion en cours',
    'reauth': 'Connexion refusée, reconnectez-vous'
};

let rows = [];
if (known) {
    rows.push({ 'lbl': 'Identifiant', 'val': account.user });
    rows.push({ 'lbl': 'Session', 'val': labels[status] || 'Non connecté' });
    if (status === 'ok') {
        rows.push({ 'lbl': 'Messages des climatiseurs', 'val': cloud.connected === true ? 'Connecté' : 'Non connecté' });
    }
    for (const id in units) {
        rows.push({ 'lbl': 'Climatiseur', 'val': units[id].name + ([units[id].indoor, units[id].outdoor].filter(m => m).length > 0 ? ' (' + [units[id].indoor, units[id].outdoor].filter(m => m).join(' / ') + ')' : '') });
        rows.push({ 'lbl': 'Identifiant MQTT', 'val': id });
    }
}

const pause = flow.get('api_pause', 'memoryOnly') || 0;
if (Date.now() < pause) {
    rows.push({ 'lbl': 'Accès suspendu', 'val': 'Trop de requêtes, reprise à ' + new Date(pause).toLocaleTimeString('fr-FR', zone) });
}

const last = flow.get('api_last', 'memoryOnly');
if (typeof last === 'object' && last !== null && last.error !== '') {
    rows.push({
        'lbl': 'Dernière erreur',
        'val': new Date(last.at).toLocaleString('fr-FR', zone) + ' - ' + last.operation + ' - HTTP ' + last.status + ' - ' + last.error
    });
}

return [
    form,
    { 'payload': rows, 'class': rows.length > 0 ? '' : 'remove' },
    known ? show : hide,
    {
        'payload': {
            'groups': {
                'show': [].concat(status === 'ok' ? [] : ['add:Connexion à Toshiba'], known ? ['add:Compte Toshiba'] : []),
                'hide': [].concat(status === 'ok' ? ['add:Connexion à Toshiba'] : [], known ? [] : ['add:Compte Toshiba'])
            }
        }
    },
    // widgets of a hidden group do not get their update: once more when the groups are shown
    msg.again === true ? null : { 'again': true, 'payload': '' }
];

// Forget account, units and their MQTT topics
// output 1: close the session / output 2: refresh UI / output 3: notification / output 4: MQTT cleanup

const describe = global.get('describe', 'memoryOnly') || {};
const account = global.get('account', 'default') || {};
const units = global.get('units', 'default') || {};
const topic = global.get('mqtt.topic', 'default') || '';
const discovery = global.get('mqtt.homeassistant', 'default') || '';
const source = 'toshiba';
const control = (describe.control || {}).unit || {};

if (typeof account.user !== 'string' || account.user === '') {

    return;
}

for (const id in units) {
    // remove retained messages
    for (const k in control) {
        const key = control[k][1];
        if (topic !== '') {
            node.send([null, null, null, { 'topic': [topic, 'discovery', source, id, key].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
            node.send([null, null, null, { 'topic': [topic, 'get', source, id, key].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
        }
        if (discovery !== '') {
            node.send([null, null, null, { 'topic': [discovery, control[k][7], source, id + '_' + key, 'config'].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
        }
    }
    if (topic !== '') {
        node.send([null, null, null, { 'topic': [topic, 'discovery', source, id].join('/'), 'payload': '', 'qos': 0, 'retain': true }]);
    }
}

global.set('account', {}, 'default');
global.set('units', {}, 'default');
global.set('history', {}, 'default');
global.set('devices', {}, 'memoryOnly');
flow.set('api_last', null, 'memoryOnly');
flow.set('last', {}, 'memoryOnly');

return [{ 'topic': 'logout', 'payload': '' }, { 'payload': '' }, { 'payload': 'Compte Toshiba déconnecté' }, null];
